methods.setWorldPaused:
setWorldPaused(on) {
    on = !!on;
    if (on === !!this._worldPaused) return;
    this._worldPaused = on;
    this.el.classList.toggle('is-world-paused', on);
    this.overLayer.classList.toggle('is-world-paused', on);
    if (on) {
      // CSS animation-play-state does not own CSS transitions or animations
      // started through Element.animate(). Park those finite effects too.
      this._worldPausedAnimations = [];
      for (const root of [this.el, this.overLayer]) {
        for (const animation of root.getAnimations?.({ subtree: true }) || []) {
          if (typeof animation.animationName === 'string' || animation.playState !== 'running') continue;
          animation.pause(); this._worldPausedAnimations.push(animation);
        }
      }
      cancelAnimationFrame(this._rafId); this._rafId = 0;
    } else {
      for (const animation of this._worldPausedAnimations || []) {
        if (animation.playState === 'paused' && animation.effect?.target?.isConnected !== false) animation.play();
      }
      this._worldPausedAnimations = null;
      if (!this.paused && this._fxMap?.size && !this._rafId) {
        this._lastFx = performance.now();
        this._rafId = requestAnimationFrame(this._fxLoop);
      }
    }
  }

methods.judge:
judge({ colors = ['#ff8a14', '#2f5bff'], percents = [50, 50], names = TEAM_NAMES, winner: authoritativeWinner = null, isCurrent = () => true } = {}) {
    const current = () => { try { return !!isCurrent(); } catch { return false; } };
    if (this._judgeDisposed || !current()) return Promise.resolve({ cancelled: true });
    this._judgeOwner?.cancel();
    return new Promise((resolve) => {
      const [pa, pb] = pct(percents[0], percents[1]);
      const ca = toHex(colors[0], '#ff8a14'), cb = toHex(colors[1], '#2f5bff');
      const shareA = pa / 100, shareB = pb / 100;
      const neutral = Math.max(0, 100 - pa - pb);
      const winner = authoritativeWinner === 0 || authoritativeWinner === 1 ? authoritativeWinner : Math.abs(pa - pb) < 0.05 ? -1 : pa > pb ? 0 : 1;
      const numA = h('b', { class: 'iw-jd__num' }, ''), numB = h('b', { class: 'iw-jd__num' }, '');
      const barA = h('div', { class: 'iw-jd__bar a' });
      const barB = h('div', { class: 'iw-jd__bar b' });
      const edgeA = h('i', { class: 'iw-jd__edge a' }), edgeB = h('i', { class: 'iw-jd__edge b' });
      const clash = h('div', { class: 'iw-jd__clash', html: splatSVG({ seed: 99, fill: '#fff', r: 50, arms: 10, drops: 8 }) });
      const wText = winner < 0 ? tr("IT'S A TIE!") : tr('{team} WINS!', { team: (names[winner] || TEAM_NAMES[winner] || '').toUpperCase() });
      const win = h('div', { class: 'iw-jd__win' + (winner === 1 ? ' is-b' : winner === 0 ? ' is-a' : ' is-tie') },
        h('div', { class: 'iw-jd__winsplat', html: splatSVG({ seed: 5, cls: 'iw-fwin', r: 58, arms: 11, drops: 5 }) }),
        h('div', { class: 'iw-jd__wintext iw-display' }, wText));
      // #894 result referees: Judd stands for the local player's team, Li'l Judd for the
      // opponent. Both stay on the stage plate for the whole judgement (win and loss alike).
      const localTeam = (() => { const me = (this.lab && this.lab.local) || (typeof G !== 'undefined' && G && G.match && G.match.local) || null; return me && me.team === 1 ? 1 : 0; })();
      // #1092: the result scene may never sample mutable post-TIME-UP paint.
      // The host freezes this PNG beside s3FinishCoverage and online followers
      // receive the same immutable value with the finish-state packet.
      const resultMap = (() => {
        const match = (typeof G !== 'undefined' && G && G.match) || null;
        const frozen = match?.s3FinishMapDataUrl;
        if (typeof frozen !== 'string' || !frozen.startsWith('data:image/png;base64,')) return null;
        try {
          const image = h('img', { class: 'iw-jd__map-snapshot' });
          image.alt = '';
          image.src = frozen;
          return image;
        } catch { return null; }
      })();
      const mapPlate = resultMap ? h('div', { class: 'iw-jd__stagemap', role: 'img', 'aria-label': 'STAGE MAP' }, resultMap) : null;
      const referee = (team, kind) => {
        const flag = h('div', { class: 'iw-jd__flag', 'aria-hidden': 'true' }, h('i', { class: 'iw-jd__pole' }), h('i', { class: 'iw-jd__cloth' }));
        const node = h('div', { class: 'iw-jd__ref ' + (team === 0 ? 'a' : 'b') + (kind === 'judd' ? ' is-judd' : ' is-liljudd'), data: { ref: kind, team: String(team) } },
          flag,
          h('div', { class: 'iw-jd__figure', html: '<svg class="iw-jd__cat" viewBox="0 0 100 100" aria-hidden="true" focusable="false"><path class="iw-jd__ear" d="M20 47 L24 11 L47 30 Z"/><path class="iw-jd__ear" d="M80 47 L76 11 L53 30 Z"/><ellipse class="iw-jd__face" cx="50" cy="58" rx="33" ry="29"/><path class="iw-jd__patch" d="M50 30c14 1 24 11 27 25-8-9-18-14-27-14-9 0-19 5-27 14 3-14 13-24 27-25z"/><circle class="iw-jd__eye" cx="38" cy="58" r="5"/><circle class="iw-jd__eye" cx="62" cy="58" r="5"/><path class="iw-jd__nose" d="M46 67h8l-4 5z"/><path class="iw-jd__mouth" d="M43 75q7 6 14 0"/><path class="iw-jd__whisker" d="M12 62h15M12 71h15M88 62H73M88 71H73"/></svg>' }),
          h('div', { class: 'iw-jd__refname iw-display' }, kind === 'judd' ? tu('JUDD') : tu("LI'L JUDD")));
        return { node, flag, team };
      };
      const refJudd = referee(localTeam, 'judd'), refLil = referee(localTeam === 0 ? 1 : 0, 'lil-judd');
      const el = h('div', { class: 'iw-jd iw-jd--refs' },
        h('div', { class: 'iw-jd__bg' }),
        h('div', { class: 'iw-jd__title iw-display' }, h('span', null, 'TURF WAR'), h('span', { class: 'iw-jd__dots' }, h('i'), h('i'), h('i'))),
        h('div', { class: 'iw-jd__refs' }, refJudd.node, refLil.node),
        h('div', { class: 'iw-jd__stage' },
          mapPlate,
          h('div', { class: 'iw-jd__arena' },
            h('div', { class: 'iw-jd__labels' },
              h('div', { class: 'iw-jd__side a' }, h('span', { class: 'iw-jd__name' }, names[0] || TEAM_NAMES[0]), numA),
              h('div', { class: 'iw-jd__side b' }, numB, h('span', { class: 'iw-jd__name' }, names[1] || TEAM_NAMES[1]))),
            h('div', { class: 'iw-jd__track' }, h('div', { class: 'iw-jd__clip' }, barA, barB), edgeA, edgeB, clash))),
        win);
      colorVars(el, 'ja', ca); colorVars(el, 'jb', cb);
      colorVars(el, 'jw', winner === 1 ? cb : ca);
      this.overLayer.appendChild(el);
      const sounds = new Set();
      const stopSound = (voice) => {
        try { if (voice?.stop) voice.stop(0); else voice?.v?.dispose?.(); } catch { /* optional audio */ }
      };
      const snd = (n) => {
        if (this._judgeOwner !== owner || !current()) { owner.cancel(); return; }
        const voice = this._snd(n);
        if (voice) {
          if (this._judgeOwner !== owner || !current()) stopSound(voice);
          else sounds.add(voice);
        }
      };

      let t = 0, drum = false, reveal = false, punched = false, finished = false;
      let tick, settled = false, removeT = null;
      const settle = (result) => { if (!settled) { settled = true; resolve(result); } };
      const cleanup = (stop) => {
        clearTimeout(removeT); removeT = null;
        el.remove();
        if (this._fxMap?.get('judge') === tick) this._fxMap.delete('judge');
        if (this._judgeOwner === owner) this._judgeOwner = null;
        if (stop) for (const voice of sounds) stopSound(voice);
        sounds.clear();
        if (!this._fxMap?.size) { cancelAnimationFrame(this._rafId); this._rafId = 0; }
      };
      const owner = { current, cancel: () => { finished = true; cleanup(true); settle({ cancelled: true }); } };
      this._judgeOwner = owner;
      // #894 reduced motion (prefers-reduced-motion, or an explicit HUD override): the
      // finished two-referee result is presented straight away instead of animated into place.
      const juddReduced = (() => { try { if (typeof this._juddReducedMotion === 'function') return !!this._juddReducedMotion(); return typeof prefersReducedMotion === 'function' ? !!prefersReducedMotion() : false; } catch { return false; } })();
      const setRefOutcome = () => {
        const tie = winner !== 0 && winner !== 1;
        for (const r of [refJudd, refLil]) {
          r.node.classList.add(tie ? 'is-tie' : (r.team === winner ? 'is-win' : 'is-lose'));
          r.flag.classList.add(tie ? 'is-flat' : (r.team === winner ? 'is-up' : 'is-down'));
        }
      };
      const t0 = this._fxTime - (juddReduced ? 3.8 : 0);
      let rollT = 0;
      const R = { a: 0, b: 0 };
      const fmt = (v) => `${v.toFixed(1)}%`;
      let trackW = 0;
      const setBars = (a, b) => {
        barA.style.transform = `scaleX(${a.toFixed(4)})`;
        barB.style.transform = `scaleX(${b.toFixed(4)})`;
        if (!trackW) trackW = barA.parentNode.offsetWidth;
        edgeA.style.transform = `translateX(${(a * trackW).toFixed(1)}px)`;
        edgeB.style.transform = `translateX(${(-b * trackW).toFixed(1)}px)`;
      };
      setBars(0, 0);
      let revealFrom = { a: 0, b: 0 };
      tick = (dt) => {
        if (this._judgeOwner !== owner || !current()) { owner.cancel(); return false; }
        if (finished) return true; // guard the original outgoing fade until its removal timer
        t = this._fxTime - t0;
        if (t < 0.8) return true;
        if (!drum) { drum = true; snd('judge_drumroll'); if (finished) return false; el.classList.add('is-racing'); }
        if (t < 3.45) {
          const k = easeOutCubic(clamp((t - 0.8) / 1.5));
          const jitter = t > 2.3 ? Math.sin(t * 38) * 0.006 + Math.sin(t * 23) * 0.004 : 0;
          R.a = 0.43 * k + jitter; R.b = 0.43 * k - jitter;
          setBars(R.a, R.b);
          rollT += dt;
          if (rollT > 0.05) {
            rollT = 0;
            // #894 the referees keep the real coverage undisclosed until the reveal, so the
            // judgement never displays a value it did not measure.
            if (t > 2.3) el.classList.add('is-drum');
          }
          return true;
        }
        if (!reveal) {
          reveal = true; snd('judge_reveal');
          if (finished) return false;
          el.classList.remove('is-drum'); el.classList.add('is-reveal');
          revealFrom = { a: R.a, b: R.b };
          clash.style.left = `${(shareA * 100).toFixed(2)}%`;
          // End-cap blobs must not paint over the unclaimed gap.
          edgeA.style.visibility = edgeB.style.visibility = neutral > 0 ? 'hidden' : '';
          clash.style.visibility = neutral > 0 ? 'hidden' : '';
        }
        const rk = juddReduced ? 1 : clamp((t - 3.45) / 0.55);
        const e = easeOutBack(rk, 2.2);
        setBars(lerp(revealFrom.a, shareA, e), lerp(revealFrom.b, shareB, e));
        const nk = juddReduced ? 1 : easeOutCubic(clamp((t - 3.45) / 0.45));
        numA.textContent = fmt(pa * nk); numB.textContent = fmt(pb * nk);
        if (!punched && t > 3.75) { punched = true; el.classList.add('is-winner', winner === 1 ? 'is-win-b' : winner === 0 ? 'is-win-a' : 'is-tie'); setRefOutcome(); }
        if (!finished && t > 5.1) {
          finished = true;
          settle({ winner });
          el.classList.add('is-out');
          removeT = setTimeout(() => cleanup(false), 650);
          return true;
        }
        return true;
      };
      this._addFx('judge', tick);
    });
  }

methods._addFx:
_addFx(name, fn) {
    this._fxMap = this._fxMap || new Map();
    this._fxMap.set(name, fn);
    if (!this._rafId && !this._worldPaused && !this.paused) { this._lastFx = performance.now(); this._rafId = requestAnimationFrame(this._fxLoop); }
  }

methods._fxLoop:
_fxLoop(t) {
    this._rafId = 0;
    if (this._worldPaused) { this._rafId = 0; return; }
    const raw = Math.min(0.25, Math.max(0, (t - this._lastFx) / 1000));
    this._lastFx = t;
    if (this._judgeOwner && !this._judgeOwner.current()) this._judgeOwner.cancel();
    if (this.paused) { this._rafId = 0; return; }
    const dt = raw * this.timeScale;
    this._fxTime += dt;
    for (const [name, fn] of this._fxMap) { let keep = true; try { keep = fn(dt) !== false; } catch (e) { console.error('[hud]', e); keep = false; } if (!keep && this._fxMap.get(name) === fn) this._fxMap.delete(name); }
    if (this._fxMap.size && !this.paused && !this._worldPaused) { if (!this._rafId) this._rafId = requestAnimationFrame(this._fxLoop); }
    else { cancelAnimationFrame(this._rafId); this._rafId = 0; }
  }

methods.run:
run({ a = '#ff8a14', b = '#2f5bff', mode = 'full', dir = 1, onMid = null, onDone = null } = {}) {
    if (this.r) this._finish();                      // never lose a pending screen swap
    const W = Math.max(1, innerWidth), H = Math.max(1, innerHeight);
    const dpr = Math.min(1.5, devicePixelRatio || 1);
    const cw = Math.round(W * dpr), ch = Math.round(H * dpr);
    if (this.cv.width !== cw || this.cv.height !== ch) { this.cv.width = cw; this.cv.height = ch; this._pat = null; }
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    const R = rng((Math.random() * 1e9) | 0);
    const r = this.r = {
      mode, dir: dir < 0 ? -1 : 1, a, b, aDark: shade(a, -0.4), bDark: shade(b, -0.36), aLight: shade(a, 0.35),
      onMid, onDone, t: 0, midDone: !onMid, W, H, R,
      dur: mode === 'light' ? 520 : mode === 'fade' ? 900 : WIPE.total, midAt: mode === 'light' ? 0 : WIPE.mid,
      ph: [[R() * TAU, R() * TAU, R() * TAU], [R() * TAU, R() * TAU, R() * TAU]],
    };
    if (mode === 'full') this._setupFull(r); else if (mode === 'light') this._setupLight(r);
    this.host.classList.add('is-run');
    this.host.dataset.mode = mode;
    this.mark.classList.remove('is-on');
    if (mode === 'full') { void this.mark.offsetWidth; this.mark.classList.add('is-on'); } // eslint-disable-line no-void
    this._last = performance.now();
    cancelAnimationFrame(this._raf);
    this._raf = requestAnimationFrame(this._frame);
    clearTimeout(this._safety);
    this._safety = setTimeout(() => { if (this.r === r) this._finish(); }, r.dur + 2600); // rAF starved (hidden tab)
    if (!r.midDone && r.midAt <= 0) { r.midDone = true; safeCall(r.onMid); }
  }

methods._frame:
_frame(now) {
    const r = this.r;
    if (!r) return;
    this._raf = requestAnimationFrame(this._frame);
    let dt = Math.min(50, Math.max(0, now - this._last));
    this._last = now;
    if (this.isFrozen()) dt = 0;
    r.t += dt * this.timeScale;
    if (!r.midDone && r.t >= r.midAt) { r.midDone = true; safeCall(r.onMid); }
    if (r.t >= r.dur) { this._finish(); return; }
    if (this.r !== r) return; // onMid started another wipe
    if (r._queuePaintT === r.t && r._queuePaintCtx === this.ctx && r._queuePaintW === this.cv.width && r._queuePaintH === this.cv.height) return;
    try {
      if (r.mode === 'full') this._drawFull(r);
      else if (r.mode === 'light') this._drawLight(r);
      else this._drawFade(r);
      r._queuePaintT = r.t; r._queuePaintCtx = this.ctx; r._queuePaintW = this.cv.width; r._queuePaintH = this.cv.height;
    } catch (e) { console.error('[ui] wipe', e); this._finish(); }
  }

methods._finish:
_finish() {
    const r = this.r;
    if (!r) return;
    this.r = null;
    cancelAnimationFrame(this._raf);
    clearTimeout(this._safety);
    if (!r.midDone) { r.midDone = true; safeCall(r.onMid); }
    this.ctx.clearRect(0, 0, r.W + 2, r.H + 2);
    if (!this.r) { this.host.classList.remove('is-run'); this.mark.classList.remove('is-on'); }
    safeCall(r.onDone);
  }

methods.update:
update(dt) {
    dt = Math.min(dt || 0, 0.1);
    this._fdt = dt;
    this._ffFrame = this.fullFrame;   // what main.js saw at the top of this frame (it didn't draw the world if true)
    if (!this._warmState && G.env) this._warmup();
    this._updateSet(dt);
    let mode = OVERLAY.has(this.mode) ? this.mode : null;
    if (!mode && this._out > 0) {
      this._out -= dt;
      if (this._out <= 0) { this._clear(); return; }
      mode = this._lastMode;
    }
    if (!mode || !this.chars.length) return;
    this.t += dt;
    this.shotT += dt;
    this.fadeIn = Math.min(1, this.fadeIn + dt / 0.25);
    if (PEDESTAL.has(mode)) this._updateLoadout(dt);
    else this._updateResults(dt);
    this.fx.update(dt, this.decks);
    this.confetti.update(dt, this.decks);
    this.sparks.update(dt);
    this.contact.instanceMatrix.needsUpdate = true;
    if (this._contactColorDirty && this.contact.instanceColor) { this.contact.instanceColor.needsUpdate = true; this._contactColorDirty = false; }
  }

methods._updateSet:
_updateSet(dt) {
    const L = this.lob;
    if (!L) return;
    const on = SET_MODES.has(this.mode);
    L.k = on && L.ready ? Math.min(1, L.k + dt / SET_FADE) : Math.max(0, L.k - dt / SET_FADE);
    if (!on && L.k <= 0) {
      // off screen: kept (parked) while you're online — a room, the hub or a trip to the locker from either;
      // released a moment after the online screens are left for good
      const net = G.net && G.net.state && G.net.state !== 'offline' && G.net.state !== 'error';
      const st = G.menus && G.menus._stack;
      const keep = net || L.room || L.preload || (st && st.some((s) => s === 'online' || s === 'lobby')) || (G.menus && (G.menus.current === 'online' || G.menus.current === 'lobby'));
      L.gone = keep ? 0 : L.gone + dt;
      if (L.gone > 1.5) this._lobRelease();
      return;
    }
    L.gone = 0;
    L.preload = false;       // shown once: from here on it follows the normal parked / released rules
    if (!L.ready) return;
    const S = L.set;
    const q = resolveLobbyQualityName(G.settings?.quality, G.mobile ?? G.game?.mobile);
    if (q !== L.quality) { L.quality = q; S.setQuality?.(q); }
    L.t += dt;
    L.shotT += dt;
    S.update?.(dt, L.t);
    // members (kids + contact shadows)
    let ci = 0;
    const memberScratch = this._lobMemberScratch || (this._lobMemberScratch = []);
    const members = this._lobMembersBusy ? [] : memberScratch;
    for (const M of L.members.values()) members.push(M);
    const wasBusy = this._lobMembersBusy; this._lobMembersBusy = true;
    try { for (const M of members) {
      this._lobStep(M, dt);
      if (M.dead || !M.c || !M.c.root.visible || ci >= 10) continue;
      const kidK = M.c.kidScale ?? (M.a.form === 'kid' ? 1 : 0);
      const hgt = Math.max(0, M.y);
      const al = kidK * (M.y < -0.05 ? 0 : 0.6 * (1 - c01(hgt / 1.4) * 0.8));
      if (al > 0.01) this._lobContact(ci++, M.pos.x, M.pos.y + 0.004, M.pos.z, 0.66 * (1 + hgt * 0.6), al);
    }
    } finally { members.length = 0; this._lobMembersBusy = wasBusy; }
    L.contact.count = ci;
    if (ci) {
      L.contact.instanceMatrix.needsUpdate = true;
      if (L.contact.instanceColor) L.contact.instanceColor.needsUpdate = true;
    }
    L.fx[0].update(dt, L.decks); L.fx[1].update(dt, L.decks);
    L.sparks.update(dt);
    L.trail.update(dt);
  }
